import{_ as o,o as d,c,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u="/plantuml/bccc6da9132ff597.svg",p=JSON.parse('{"title":"Java阻塞队列简介","description":"","frontmatter":{"title":"Java阻塞队列简介","date":"2022-08-01","categories":["编程语言","Java"],"tags":["Java","并发"]},"headers":[],"relativePath":"编程语言/Java阻塞队列简介.md","filePath":"编程语言/Java阻塞队列简介.md"}'),a={name:"编程语言/Java阻塞队列简介.md"};function n(r,e,i,l,k,s){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="java阻塞队列简介" tabindex="-1">Java阻塞队列简介 <a class="header-anchor" href="#java阻塞队列简介" aria-label="Permalink to &quot;Java阻塞队列简介&quot;">​</a></h1><p>Java阻塞队列是一种可以实现<strong>阻塞插入</strong>和<strong>阻塞移除</strong>的特殊队列，它被广泛应用于生产者消费者模式。如在线程池中，可以使用<code>LinkedBlockingQueue</code>与<code>SynchronousQueue</code>等阻塞队列来生产与消费线程对象。</p><p>下面将简单介绍Java中常用的几个阻塞队列。</p><h2 id="一阻塞队列汇总" tabindex="-1">一、阻塞队列汇总 <a class="header-anchor" href="#一阻塞队列汇总" aria-label="Permalink to &quot;一、阻塞队列汇总&quot;">​</a></h2><p>阻塞队列位于<code>JUC</code>包(即<code>java.util.concurrent</code>包)，该包保存了Java并发的大多数类，如：锁、阻塞队列、线程池等。</p><p>JUC下的阻塞队列共有3个接口与7个实现类，他们的关系如下所示：</p><img class="diagram-image" src="'+u+'" alt="" width="1361" height="323" loading="lazy" decoding="async"><p>上述类图中，<code>BlockingQueue</code>是阻塞队列的顶层接口，<code>BlockingDeque</code>与<code>TransferQueue</code>则是继承自<code>BlockingQueue</code>的两个用于实现特殊功能的接口。剩下的7个阻塞队列实现类均实现了上述3个接口，它们如下所示：</p><table tabindex="0"><thead><tr><th>阻塞队列类</th><th>JDK版本</th><th>有界性</th></tr></thead><tbody><tr><td>ArrayBlockingQueue</td><td>5</td><td>有界(bounded)</td></tr><tr><td>LinkedBlockingQueue</td><td>5</td><td>有界(optionally-bounded)</td></tr><tr><td>PriorityBlockingQueue</td><td>5</td><td>无界(unbounded)</td></tr><tr><td>DelayQueue</td><td>5</td><td>无界(unbounded)</td></tr><tr><td>SynchronousQueue</td><td>5</td><td>-</td></tr><tr><td>LinkedBlockingDeque</td><td>6</td><td>有界(optionally-bounded)</td></tr><tr><td>LinkedTransferQueue</td><td>7</td><td>无界(unbounded)</td></tr></tbody></table><blockquote><p>除了阻塞队列外，JUC包下还有一个非阻塞队列：<code>ConcurrentLinkedQueue</code>，该类不在本节讨论之中。</p></blockquote><h2 id="二阻塞队列概述" tabindex="-1">二、阻塞队列概述 <a class="header-anchor" href="#二阻塞队列概述" aria-label="Permalink to &quot;二、阻塞队列概述&quot;">​</a></h2><h3 id="一阻塞队列的抽象定义blockingqueue" tabindex="-1">（一）阻塞队列的抽象定义：BlockingQueue <a class="header-anchor" href="#一阻塞队列的抽象定义blockingqueue" aria-label="Permalink to &quot;（一）阻塞队列的抽象定义：BlockingQueue&quot;">​</a></h3><p><code>BlockingQueue</code>定义了阻塞队列的抽象结构，所有的阻塞队列都需要实现它。<code>BlockingQueue</code>的核心方法如下所示：</p><table tabindex="0"><thead><tr><th>方法</th><th>抛出异常</th><th>返回特殊值</th><th>阻塞</th><th>超时阻塞</th></tr></thead><tbody><tr><td>插入</td><td>add(e)</td><td>offer(e)</td><td>put(e)</td><td>offer(e, time, unit)</td></tr><tr><td>移除</td><td>remove()</td><td>poll()</td><td>take()</td><td>poll(time, unit)</td></tr><tr><td>检查</td><td>element()</td><td>peek()</td><td>-</td><td>-</td></tr></tbody></table><p>在对队列执行以下三种操作时：</p><ol><li>在队列满时插入元素：使用<code>add</code>、<code>offer</code>、<code>put</code>插入方法</li><li>在队列空时移除元素：使用<code>remove</code>、<code>poll</code>、<code>take</code>移除方法</li><li>在队列空时检查元素：使用<code>element</code>、<code>peek</code>检查方法</li></ol><p>一定会执行失败，此时根据使用方法的不同，可能会出现以下四种情况：</p><ol><li>抛出异常</li><li>返回特殊值(如null或false)</li><li>阻塞</li><li>超时阻塞</li></ol><p>其中，只有<strong>阻塞</strong>与<strong>超时阻塞</strong>的4个方法是<code>BlockingQueue</code>接口独有的(这也是阻塞队列需要重点关注的方法)，而<strong>抛出异常</strong>与<strong>返回特殊值</strong>的6个方法则是继承自<code>Queue</code>接口。后续讲到的几种具体的阻塞队列实现，都需要实现上述方法。</p><h3 id="二常规阻塞队列arrayblockingqueue与linkedblockingqueue" tabindex="-1">（二）常规阻塞队列：ArrayBlockingQueue与LinkedBlockingQueue <a class="header-anchor" href="#二常规阻塞队列arrayblockingqueue与linkedblockingqueue" aria-label="Permalink to &quot;（二）常规阻塞队列：ArrayBlockingQueue与LinkedBlockingQueue&quot;">​</a></h3><p><code>ArrayBlockingQueue</code>是使用<strong>数组</strong>实现的有界(bounded)阻塞队列，<code>LinkedBlockingQueue</code>是使用<strong>链表</strong>实现的有界(optionally-bounded)阻塞队列。它们都符合普通队列的<code>FIFO</code>(first-in-first-out，先入先出)原则：新增元素时在队尾插入，移除元素时从队首删除，队首的元素存在时间最长，队尾元素存在时间最短。</p><p>为了实现阻塞插入或阻塞移除，<code>ArrayBlockingQueue</code>与<code>LinkedBlockingQueue</code>均使用<code>ReentrantLock</code>锁来实现同步，当队列满时或队列空时，执行阻塞的插入或移除操作(如:<code>put</code>或<code>take</code>)，会导致持有锁的线程将进入自旋等待状态，而其它线程因为无法获取到锁，也将进入等待状态，直到队列非满或非空时，等待状态才可以解除。</p><p>其中，<code>ArrayBlockingQueue</code>只有一个锁，可以通过构造函数的<code>fair</code>参数来指定该锁的公平性。而<code>LinkedBlockingQueue</code>则有两个锁：<code>takeLock</code>与<code>putLock</code>，它们都是默认的非公平锁，<code>takeLock</code>可以由<code>take</code>、<code>poll</code>等方法持有，<code>putLock</code>可以由<code>put</code>、<code>offe</code>等方法持有。</p><p><code>LinkedBlockingQueue</code>可以用来实现<code>FixedThreadPool</code>线程池(详见<code>Executors</code>的<code>newFixedThreadPool(int nThreads)</code>方法)。</p><p>在大多数并发应用中，<code>LinkedBlockingQueue</code>比<code>ArrayBlockingQueue</code>有更高的吞吐量，但有更低的性能可预测性(<em>Linked queues typically have higher throughput than array-based queues but less predictable performance in most concurrent applications.</em>)</p><h3 id="三优先阻塞队列priorityblockingqueue与delayqueue" tabindex="-1">（三）优先阻塞队列：PriorityBlockingQueue与DelayQueue <a class="header-anchor" href="#三优先阻塞队列priorityblockingqueue与delayqueue" aria-label="Permalink to &quot;（三）优先阻塞队列：PriorityBlockingQueue与DelayQueue&quot;">​</a></h3><p><code>PriorityBlockingQueue</code>和<code>DelayQueue</code>都是使用<code>PriorityQueue</code>实现的无界(unbounded)阻塞队列，它们都使用<code>ReentrantLock</code>锁来实现同步。</p><p>其中，<code>PriorityBlockingQueue</code>可以通过<code>Comparator</code>来自定义队列元素的优先级。<code>DelayQueue</code>通过<code>Delayed</code>泛型元素实现延时获取元素。<code>DelayQueue</code>可以用来设计缓存系统与定时任务调度。</p><h3 id="四无容量阻塞队列synchronousqueue" tabindex="-1">（四）无容量阻塞队列：SynchronousQueue <a class="header-anchor" href="#四无容量阻塞队列synchronousqueue" aria-label="Permalink to &quot;（四）无容量阻塞队列：SynchronousQueue&quot;">​</a></h3><p><code>SynchronousQueue</code>是一个没有任何容量的阻塞队列(其<code>capacity</code>值为0)，每一个插入操作都必须等待另一个线程对应的移除操作，反之亦然。<code>SynchronousQueue</code>使用<code>ReentrantLock</code>锁来实现同步，可以通过<code>fair</code>参数来指定该锁的公平性。</p><p><code>SynchronousQueue</code>可以用来实现<code>CachedThreadPool</code>线程池(详见<code>Executors</code>的<code>newCachedThreadPool()</code>方法)。</p><h3 id="五双向阻塞队列blockingdeque与linkedblockingdeque" tabindex="-1">（五）双向阻塞队列：BlockingDeque与LinkedBlockingDeque <a class="header-anchor" href="#五双向阻塞队列blockingdeque与linkedblockingdeque" aria-label="Permalink to &quot;（五）双向阻塞队列：BlockingDeque与LinkedBlockingDeque&quot;">​</a></h3><p><code>LinkedBlockingDeque</code>是使用双向链表实现的有界(optionally-bounded)阻塞队列，它实现了<code>BlockingDeque</code>接口。<code>LinkedBlockingDeque</code>使用<code>ReentrantLock</code>锁来实现同步。</p><p><code>LinkedBlockingDeque</code>可以用来实现工作窃取模式(即ForkJoin系列类)。</p><h3 id="六transfer阻塞队列transferqueue与linkedtransferqueue" tabindex="-1">（六）Transfer阻塞队列：TransferQueue与LinkedTransferQueue <a class="header-anchor" href="#六transfer阻塞队列transferqueue与linkedtransferqueue" aria-label="Permalink to &quot;（六）Transfer阻塞队列：TransferQueue与LinkedTransferQueue&quot;">​</a></h3><p><code>LinkedTransferQueue</code>是使用链表实现的无界(unbounded)阻塞队列，它实现了<code>TransferQueue</code>接口。</p><p>可以将<code>LinkedTransferQueue</code>看作是<code>LinkedBlockingQueue</code>与<code>SynchronousQueue</code>的结合。<code>LinkedTransferQueue</code>的<code>transfer</code>方法会优先将生产者传入的元素立刻传输给消费者，此过程类似于<code>SynchronousQueue</code>。如果没有对应的消费者生产者传入的元素，会将之放到队列中，此过程类似于<code>LinkedTransferQueue</code>。</p><h2 id="三总结" tabindex="-1">三、总结 <a class="header-anchor" href="#三总结" aria-label="Permalink to &quot;三、总结&quot;">​</a></h2><p>JUC包下定义了10个阻塞队列相关的接口或类。简单将它们分下类如下所示：</p><ul><li><code>BlockingQueue</code>作为顶层接口定义了阻塞队列的阻塞队列</li><li><code>ArrayBlockingQueue</code>与<code>LinkedBlockingQueue</code>是两个最基础的阻塞队列实现</li><li><code>PriorityBlockingQueue</code>与<code>DelayQueue</code>是实现了优先级与延时获取的阻塞队列</li><li><code>SynchronousQueue</code>是不存储元素并直接传递元素的阻塞队列</li><li><code>LinkedBlockingDeque</code>是实现了<code>BlockingDeque</code>接口的双向阻塞队列</li><li><code>LinkedTransferQueue</code>是实现了<code>TransferQueue</code>接口的阻塞队列，可以将其看作<code>LinkedBlockingQueue</code>与<code>SynchronousQueue</code>的结合。</li></ul><p>本文更偏向于阻塞队列基础概念的简介，很多内容只是一笔带过，没有详细介绍，由于理解有限，上述内容可能会有偏差，后续将按需修改或增加相关内容。</p><p>锁是阻塞队列的基础，上面提到的大部分阻塞队列都是使用<code>ReentrantLock</code>锁来实现同步。同时，阻塞队列又是线程池的基础，有关线程池的内容，将在后续介绍。</p><blockquote><p>参考文档</p></blockquote><ol><li>《Java并发编程的艺术 方腾飞 魏鹏 程晓明 著》</li></ol>',44)])])}const g=o(a,[["render",n]]);export{p as __pageData,g as default};
